--
-- Table structure for table `vd_video`
--

DROP TABLE IF EXISTS `vd_video`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vd_video` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT 'id',
  `user_id` bigint unsigned NOT NULL COMMENT '用户id',
  `video_url` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '存储地址',
  `upload_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上传时间',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '视频处理状态（如：0:待处理、1:处理中、2:已完成）',
  `title` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '视频标题',
  `thumbnail` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci COMMENT '缩略图地址',
  `extension` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '文件扩展名',
  `processed_url` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '处理后的地址',
  `fire_probability` double DEFAULT NULL COMMENT '火灾概率',
  `smoke_probability` double DEFAULT NULL COMMENT '烟雾概率',
  `process_time` datetime DEFAULT NULL COMMENT '处理时间',
  `place_id` bigint DEFAULT NULL COMMENT '地点id',
  `d_time` int DEFAULT NULL COMMENT '视频时长(s)',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `vd_video_vd_user_FK` (`user_id`) USING BTREE,
  CONSTRAINT `vd_video_vd_user_FK` FOREIGN KEY (`user_id`) REFERENCES `vd_user` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=12258080902113 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

